                        #pragma unroll
                        for (int r = 0; r < OUTPUTS_PER_THREAD; ++r) {
                            const int spatial_local = tx + r * TILE_IC;
                            const int spatial =
                                int(blockIdx.x) * TILE_SPATIAL + spatial_local;
                            if (spatial < total_spatial) {
                                #pragma unroll
                                for (int j = 0; j < TILE_IC; ++j) {
                                    const int channel = ic_tile + j;
                                    if (channel < ic_per_group) {
