                        }
                    }
                    __syncthreads();
                }
            }
        }
    }
    if (valid_oc) {
        #pragma unroll
        for (int r = 0; r < OUTPUTS_PER_THREAD; ++r) {
            const int spatial = spatial_base + r * TILE_IC;
            if (spatial < total_spatial) {
                const int hw = HO * WO;
                const int od = spatial / hw;
                const int rem = spatial - od * hw;
                const int oh = rem / WO;
                const int ow = rem - oh * WO;
