                            const int ih_num = oh + pad_h - kh;
                            const int iw_num = ow + pad_w - kw;
                            const bool d_valid =
                                id_num >= 0 &&
                                (id_num % stride_d == 0) &&
                                (id_num / stride_d) < DI;
                            const bool h_valid =
