                                (iw_num % stride_w == 0) &&
                                (iw_num / stride_w) < WI;

                            if (d_valid && h_valid && w_valid) {
                                const int id = id_num / stride_d;
                                const int ih = ih_num / stride_h;
                                const int iw = iw_num / stride_w;
                                 const int64_t x_index =
                                     ((int64_t(batch) * IC +
                                       int64_t(ic_group_start + channel)) * DI + id) * HI * WI +
