            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

        self._stride = tuple(stride)
        self._padding = tuple(padding)
        self._output_padding = tuple(output_padding)
        self._groups = groups
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias = torch.empty(
                0,
                device=x.device,
                dtype=x.dtype,
            )

        return self._ext.cute_conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            bias,
            int(self._stride[0]),
            int(self._stride[1]),
            int(self._stride[2]),
            int(self._padding[0]),
            int(self._padding[1]),
            int(self._padding[2]),
            int(self._output_padding[0]),
            int(self._output_padding[1]),
            int(self._output_padding[2]),
            int(self._groups),
        )
